from state import CircuitState
from metrics import CircuitMetrics
from typing import Callable, Any

class CircuitBreakerOpenException(Exception):
    pass

class CircuitBreaker:
    def __init__(self, failure_threshold: int = 3, recovery_timeout: float = 10.0, success_threshold: int = 2):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.success_threshold = success_threshold
        self.state = CircuitState.CLOSED
        self.metrics = CircuitMetrics()

    def record_success(self) -> None:
        if self.state == CircuitState.HALF_OPEN:
            self.metrics.success_count += 1
            # Bug: checks >= failure_threshold instead of success_threshold to close circuit
            if self.metrics.success_count >= self.failure_threshold:
                self.state = CircuitState.CLOSED
                self.metrics.failure_count = 0
                self.metrics.success_count = 0
        elif self.state == CircuitState.CLOSED:
            self.metrics.failure_count = 0

    def record_failure(self, now: float) -> None:
        if self.state == CircuitState.HALF_OPEN:
            self.state = CircuitState.OPEN
            self.metrics.last_state_change = now
        elif self.state == CircuitState.CLOSED:
            self.metrics.failure_count += 1
            if self.metrics.failure_count >= self.failure_threshold:
                self.state = CircuitState.OPEN
                self.metrics.last_state_change = now

    def can_execute(self, now: float) -> bool:
        if self.state == CircuitState.CLOSED:
            return True
        if self.state == CircuitState.OPEN:
            if now - self.metrics.last_state_change >= self.recovery_timeout:
                self.state = CircuitState.HALF_OPEN
                self.metrics.success_count = 0
                return True
            return False
        return True # HALF_OPEN

